/*
 * ufs_all_test — end-to-end validation of the user-space filesystem host
 * (ufsd) across all backends.
 *
 * QEMU layout (DEV_CLASS_BLOCK indices):
 *   0  bus.0 primary storage fat32.img (used for kernel boot)
 *   1  bus.2 fat scratch (existing UFS_SCRATCH_IMG, contains HELLO.TXT)
 *   2  bus.4 ext4 scratch (mke2fs -d preseeded with hello.txt)
 *   3  bus.6 iso9660 (generated by mkisofs_test, contains HELLO.TXT and
 *      SUB/NESTED.TXT)
 *   4  bus.7 ntfs scratch (quick-formatted with mkntfs, empty volume)
 *
 * Each backend brings up its own ufsd instance and runs a POSIX operation
 * sequence:
 *   fat : read back / write then read back / list directory / delete
 *   ext4: read back preseeded content / create-write-read / rename / delete
 *   iso : verify read-only content / list directory / read nested path
 *   ntfs: mount parse / create-write-read-back / directory ops / SIGKILL
 *         restart persistence / delete
 */
#define _GNU_SOURCE
#include "../../liba20rt/a20_arch.h"
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <dirent.h>
#include <errno.h>
#include <signal.h>
#include <sys/wait.h>
#include <sys/mount.h>

static int fail(const char *tag, const char *why)
{
    printf("%s: FAIL %s\n", tag, why);
    return 1;
}

static int release_boot_ext4_owner(void)
{
    static const char *const paths[] = {
        "/extra/dev/shm", "/extra/dev", "/extra/proc", "/extra/sys",
        "/extra/run", "/extra"
    };
    for (size_t i = 0; i < sizeof(paths) / sizeof(paths[0]); i++) {
        if (umount2(paths[i], 0) != 0 && errno != EINVAL)
            return -1;
    }
    return 0;
}

static pid_t spawn_ufsd(const char *mp, const char *idx, const char *fstype)
{
    /* Startup may already have mounted the first ext4 block device at
     * /extra.  Release that native owner before any test registers UXFS for
     * the same device; never rely on two simultaneous writable mounts. */
    if (strcmp(fstype, "ext4") == 0 && release_boot_ext4_owner() != 0)
        return -1;
    pid_t pid = fork();
    if (pid == 0) {
        execl(A20_NATIVE_BIN("ufsd"), "ufsd", mp, idx, fstype, (char *)0);
        _exit(90);
    }
    return pid;
}

/* Shared crash-recovery sequence: SIGKILL the instance -> reap -> unmount
 * (the kernel-side mount still points at the dead channel, so it must be
 * unmounted before it can be re-registered) -> bring it back up. */
static int kill_and_remount_ufsd(pid_t victim, const char *mp,
                                 const char *idx, const char *fstype)
{
    kill(victim, SIGKILL);
    waitpid(victim, NULL, 0);
    if (umount2(mp, 0) != 0)
        return -1;
    spawn_ufsd(mp, idx, fstype);
    return 0;
}

static int wait_path(const char *path, int tries)
{
    struct stat st;
    for (int i = 0; i < tries; i++) {
        if (stat(path, &st) == 0)
            return 0;
        usleep(20000);
    }
    return -1;
}

static int read_all(const char *path, char *buf, size_t cap)
{
    int fd = open(path, O_RDONLY);
    if (fd < 0)
        return -1;
    ssize_t n = read(fd, buf, cap - 1);
    close(fd);
    if (n < 0)
        return -1;
    buf[n] = '\0';
    return (int)n;
}

static int scan_dir_repeatedly(const char *pair, const char *path,
                               const char *wanted, const char *forbidden)
{
    for (int pass = 0; pass < 128; pass++) {
        DIR *d = opendir(path);
        if (!d) {
            printf("UXFS_READDIR: FAIL pair=%s path=%s pass=%d opendir errno=%d\n",
                   pair, path, pass, errno);
            fflush(stdout);
            return 1;
        }
        int saw_wanted = 0, saw_forbidden = 0;
        unsigned entries = 0;
        struct dirent *ent;
        errno = 0;
        while ((ent = readdir(d)) != NULL) {
            entries++;
            if (strcmp(ent->d_name, wanted) == 0)
                saw_wanted = 1;
            if (strcmp(ent->d_name, forbidden) == 0)
                saw_forbidden = 1;
        }
        int read_errno = errno;
        int close_rc = closedir(d);
        if (close_rc != 0 || !saw_wanted || saw_forbidden) {
            printf("UXFS_READDIR: FAIL pair=%s path=%s pass=%d entries=%u wanted=%d forbidden=%d close=%d read_errno=%d\n",
                   pair, path, pass, entries, saw_wanted, saw_forbidden,
                   close_rc, read_errno);
            fflush(stdout);
            return 1;
        }
    }
    return 0;
}

static int run_concurrent_readdir_pair(const char *tag, const char *path_a,
                                       const char *path_b)
{
    static const char *const want[] = { "ONLY_A", "ONLY_B" };
    static const char *const reject[] = { "ONLY_B", "ONLY_A" };
    const char *const path[] = { path_a, path_b };
    for (int i = 0; i < 2; i++) {
        if (mkdir(path[i], 0755) != 0) {
            printf("UXFS_READDIR: FAIL pair=%s mkdir path=%s errno=%d\n",
                   tag, path[i], errno);
            return -1;
        }
        char marker[64];
        snprintf(marker, sizeof(marker), "%s/%s", path[i], want[i]);
        int fd = open(marker, O_CREAT | O_WRONLY, 0644);
        if (fd < 0 || close(fd) != 0) {
            printf("UXFS_READDIR: FAIL pair=%s create path=%s errno=%d\n",
                   tag, marker, errno);
            return -1;
        }
    }
    pid_t child[2];
    for (int i = 0; i < 2; i++) {
        child[i] = fork();
        if (child[i] < 0)
            return -1;
        if (child[i] == 0)
            _exit(scan_dir_repeatedly(tag, path[i], want[i], reject[i]));
    }
    int failed = 0;
    for (int i = 0; i < 2; i++) {
        int status = 0;
        if (waitpid(child[i], &status, 0) != child[i] ||
            !WIFEXITED(status) || WEXITSTATUS(status) != 0) {
            printf("UXFS_READDIR: FAIL pair=%s child=%d status=0x%x\n",
                   tag, i, status);
            failed = 1;
        }
    }
    for (int i = 0; i < 2; i++) {
        char marker[64];
        snprintf(marker, sizeof(marker), "%s/%s", path[i], want[i]);
        if (unlink(marker) != 0 || rmdir(path[i]) != 0) {
            printf("UXFS_READDIR: FAIL pair=%s cleanup path=%s errno=%d\n",
                   tag, path[i], errno);
            failed = 1;
        }
    }
    return failed ? -1 : 0;
}

/* Exercise simultaneous RPC reply decoding both within one mounted volume
 * and across independent superblocks, where request locks cannot serialize. */
static int test_concurrent_readdir(void)
{
    if (run_concurrent_readdir_pair("same-sb", "/untfs/ra", "/untfs/rb") != 0)
        return -1;
    printf("UXFS_READDIR: same-sb PASS\n");
    if (run_concurrent_readdir_pair("cross-sb", "/untfs/rc", "/uext4/rd") != 0)
        return -1;
    printf("UXFS_READDIR: cross-sb PASS\n");
    return 0;
}

static int test_readdir_only(void)
{
    if (spawn_ufsd("/uext4", "2", "ext4") < 0 ||
        wait_path("/uext4/hello.txt", 500))
        return fail("UXFS_READDIR", "ext4 service mount");
    if (spawn_ufsd("/untfs", "4", "ntfs") < 0 ||
        wait_path("/untfs", 500))
        return fail("UXFS_READDIR", "ntfs service mount");
    if (test_concurrent_readdir() != 0)
        return fail("UXFS_READDIR", "concurrent readdir");
    printf("UXFS_READDIR: PASS\n");
    return 0;
}

static unsigned char pattern[8192];

static int roundtrip(const char *tag, const char *dir, const char *name)
{
    char path[256];
    snprintf(path, sizeof(path), "%s/%s", dir, name);

    for (size_t i = 0; i < sizeof(pattern); i++)
        pattern[i] = (unsigned char)(i * 31 + 7);

    int fd = open(path, O_CREAT | O_TRUNC | O_WRONLY, 0644);
    if (fd < 0) {
        printf("%s: create errno=%d (%s)\n", tag, errno, path);
        return fail(tag, "create");
    }
    ssize_t wn = write(fd, pattern, sizeof(pattern));
    if (wn != (ssize_t)sizeof(pattern))
        printf("%s: write ret=%zd errno=%d\n", tag, wn, errno);
    close(fd);
    if (wn != (ssize_t)sizeof(pattern))
        return fail(tag, "write size");

    static unsigned char back[8192];
    fd = open(path, O_RDONLY);
    if (fd < 0) {
        printf("%s: reopen errno=%d\n", tag, errno);
        return fail(tag, "reopen");
    }
    ssize_t rn = read(fd, back, sizeof(back));
    close(fd);
    if (rn != (ssize_t)sizeof(pattern)) {
        printf("%s: read ret=%zd errno=%d\n", tag, rn, errno);
        return fail(tag, "read size");
    }
    for (size_t i = 0; i < sizeof(pattern); i++) {
        if (pattern[i] != back[i]) {
            printf("%s: first diff at %zu want=%02x got=%02x\n",
                   tag, i, pattern[i], back[i]);
            break;
        }
    }
    if (memcmp(pattern, back, sizeof(pattern)) != 0)
        return fail(tag, "read-back mismatch");
    return 0;
}

static int test_fat(void)
{
    const char *tag = "UXFS_FAT";
    struct stat st0;
    if (stat("/ufs/HELLO.TXT", &st0) != 0)
        spawn_ufsd("/ufs", "1", "fat"); /* fallback self-start when
                            * svcmgr is not
                            * supervising */
    if (wait_path("/ufs/HELLO.TXT", 500))
        return fail(tag, "/ufs not visible");

    char buf[64];
    if (read_all("/ufs/HELLO.TXT", buf, sizeof(buf)) <= 0 ||
        strcmp(buf, "hello-uxfs\n") != 0)
        return fail(tag, "content mismatch");

    if (roundtrip(tag, "/ufs", "ROUND.BIN"))
        return 1;
    if (unlink("/ufs/ROUND.BIN") != 0)
        return fail(tag, "unlink");

    printf("%s: PASS\n", tag);
    return 0;
}

static const char *g_ext4_stop_stage;

static int ext4_stage_done(const char *stage)
{
    printf("UXFS_EXT4_STAGE: %s\n", stage);
    return g_ext4_stop_stage && strcmp(g_ext4_stop_stage, stage) == 0;
}

static int test_ext4(void)
{
    const char *tag = "UXFS_EXT4";
    spawn_ufsd("/uext4", "2", "ext4");
    if (wait_path("/uext4/hello.txt", 500))
        return fail(tag, "/uext4 not visible");

    char buf[64];
    if (read_all("/uext4/hello.txt", buf, sizeof(buf)) <= 0 ||
        strcmp(buf, "hello ext4 user-space\n") != 0)
        return fail(tag, "seeded content mismatch");

    if (roundtrip(tag, "/uext4", "EXT4BIN.BIN"))
        return 1;
    if (ext4_stage_done("created"))
        return 0;

    /* rename semantics (ext4 supports the full rename primitive) */
    if (rename("/uext4/EXT4BIN.BIN", "/uext4/RENAMED.BIN") != 0)
        return fail(tag, "rename");
    struct stat st;
    if (stat("/uext4/EXT4BIN.BIN", &st) == 0 || stat("/uext4/RENAMED.BIN", &st) != 0)
        return fail(tag, "rename effect");
    if (ext4_stage_done("renamed"))
        return 0;

    if (unlink("/uext4/RENAMED.BIN") != 0) {
        printf("%s: unlink errno=%d\n", tag, errno);
        return fail(tag, "unlink");
    }
    if (ext4_stage_done("unlinked"))
        return 0;

    printf("%s: PASS\n", tag);
    return 0;
}

static int test_ext4_open_unlink(void)
{
    const char *tag = "UXFS_EXT4_OPEN_UNLINK";
    const char *a = "/uext4/LIFETIME.BIN";
    const char *b = "/uext4/LIFETIME.HL";
    spawn_ufsd("/uext4", "2", "ext4");
    if (wait_path("/uext4/hello.txt", 500))
        return fail(tag, "mount not visible");
    printf("%s: mounted\n", tag);

    int fd = open(a, O_CREAT | O_TRUNC | O_RDWR, 0644);
    if (fd < 0) return fail(tag, "create/open");
    printf("%s: opened first\n", tag);
    static const char first[] = "open-unlink-before\n";
    if (write(fd, first, sizeof(first) - 1) != (ssize_t)(sizeof(first) - 1) ||
        fsync(fd) != 0)
        return fail(tag, "initial write/fsync");
    if (link(a, b) != 0)
        return fail(tag, "hard link");
    printf("%s: linked\n", tag);
    if (unlink(a) != 0)
        return fail(tag, "unlink non-final hard link");
    printf("%s: unlinked first name\n", tag);
    struct stat st;
    if (stat(b, &st) != 0 || st.st_nlink != 1)
        return fail(tag, "remaining hard link lost");
    if (lseek(fd, 0, SEEK_SET) != 0)
        return fail(tag, "seek linked fd");
    char bytes[64] = {0};
    if (read(fd, bytes, sizeof(bytes)) != (ssize_t)(sizeof(first) - 1) ||
        memcmp(bytes, first, sizeof(first) - 1) != 0)
        return fail(tag, "read after non-final unlink");
    if (close(fd) != 0)
        return fail(tag, "close non-final unlink fd");
    printf("%s: closed first fd\n", tag);

    fd = open(b, O_RDWR);
    if (fd < 0) return fail(tag, "open final link");
    printf("%s: opened final link\n", tag);
    if (unlink(b) != 0)
        return fail(tag, "unlink final hard link");
    printf("%s: unlinked final name\n", tag);
    if (stat(b, &st) == 0)
        return fail(tag, "unlinked name still resolves");
    if (lseek(fd, 0, SEEK_END) != (long)(sizeof(first) - 1))
        return fail(tag, "seek open-unlinked fd");
    static const char second[] = "after-unlink\n";
    if (write(fd, second, sizeof(second) - 1) != (ssize_t)(sizeof(second) - 1) ||
        fsync(fd) != 0)
        return fail(tag, "write/fsync after unlink");
    if (lseek(fd, 0, SEEK_SET) != 0)
        return fail(tag, "rewind open-unlinked fd");
    memset(bytes, 0, sizeof(bytes));
    size_t expected = sizeof(first) + sizeof(second) - 2;
    if (read(fd, bytes, expected) != (ssize_t)expected ||
        memcmp(bytes, first, sizeof(first) - 1) != 0 ||
        memcmp(bytes + sizeof(first) - 1, second, sizeof(second) - 1) != 0)
        return fail(tag, "open-unlinked data mismatch");
    if (close(fd) != 0)
        return fail(tag, "last close cleanup");
    printf("%s: last close complete\n", tag);
    sync();
    printf("%s: PASS\n", tag);
    return 0;
}

static uint8_t g_close_retry_multi_payload[8192];

static int test_ext4_close_retry(int multi)
{
    int quarantine = multi == 2;
    const char *tag = quarantine ? "UXFS_EXT4_CLOSE_QUARANTINE" :
        (multi ? "UXFS_EXT4_CLOSE_RETRY_MULTI" : "UXFS_EXT4_CLOSE_RETRY");
    const char *target = multi ? "/uext4/CLOSE-RETRY-MULTI.BIN" :
                                 "/uext4/CLOSE-RETRY.BIN";
    const char *keeper = "/uext4/CLOSE-KEEPER.BIN";
    spawn_ufsd("/uext4", "2", "ext4");
    if (wait_path("/uext4/hello.txt", 500))
        return fail(tag, "mount not visible");

    int keepfd = open(keeper, O_CREAT | O_TRUNC | O_RDWR, 0644);
    int fd = open(target, O_CREAT | O_TRUNC | O_RDWR, 0644);
    if (keepfd < 0 || fd < 0) return fail(tag, "create/open");
    struct stat target_st;
    if (fstat(fd, &target_st) != 0) return fail(tag, "stat target before unlink");
    printf("%s: target ino=%lu size=%lu blocks=%lu\n", tag,
           (unsigned long)target_st.st_ino,
           (unsigned long)target_st.st_size,
           (unsigned long)target_st.st_blocks);
    if (multi) {
        memset(g_close_retry_multi_payload, 0xa5,
               sizeof(g_close_retry_multi_payload));
        for (size_t offset = 0; offset < sizeof(g_close_retry_multi_payload); ) {
            size_t count = sizeof(g_close_retry_multi_payload) - offset;
            if (count > 512) count = 512;
            ssize_t written = write(fd, g_close_retry_multi_payload + offset,
                                    count);
            if (written != (ssize_t)count)
                return fail(tag, "multi-block write");
            offset += count;
        }
        if (fsync(fd) != 0)
            return fail(tag, "multi-block fsync");
        if (lseek(fd, 0, SEEK_SET) != 0)
            return fail(tag, "multi-block rewind");
        uint8_t readback[sizeof(g_close_retry_multi_payload)];
        if (read(fd, readback, sizeof(readback)) != (ssize_t)sizeof(readback) ||
            memcmp(readback, g_close_retry_multi_payload, sizeof(readback)) != 0)
            return fail(tag, "multi-block data readback");
        printf("%s: wrote and read back %lu bytes\n", tag,
               (unsigned long)sizeof(g_close_retry_multi_payload));
    } else {
        static const char content[] = "close cleanup retry\n";
        if (write(fd, content, sizeof(content) - 1) !=
                (ssize_t)(sizeof(content) - 1))
            return fail(tag, "initial write");
    }
    if (fsync(fd) != 0) return fail(tag, "initial fsync");
    if (unlink(target) != 0) return fail(tag, "unlink final name");
    errno = 0;
    int close_rc = close(fd);
    int close_errno = errno;
    int expected_errno = quarantine ? 117 : EIO;
    int close_expected = close_rc < 0 && close_errno == expected_errno;
    printf("%s: first close rc=%d errno=%d\n", tag, close_rc,
           close_rc < 0 ? close_errno : 0);
    if (close_expected)
        printf("%s: first close returned errno=%d\n", tag, close_errno);
    else
        printf("%s: first close did not return expected errno=%d\n", tag,
               expected_errno);
    if (close_rc < 0) {
        errno = 0;
        if (fcntl(fd, F_GETFD) != -1 || errno != EBADF)
            return fail(tag, "failed close did not consume the descriptor");
        printf("%s: old fd consumed (EBADF)\n", tag);
    }
    if (quarantine) {
        errno = 0;
        int create_rc = open("/uext4/QUARANTINE-NEW.BIN",
                             O_CREAT | O_RDWR, 0644);
        if (create_rc >= 0 || errno != 117)
            return fail(tag, "mutation was not rejected after fatal rollback");
        printf("%s: later create rejected errno=117\n", tag);
        errno = 0;
        int sync_rc = fsync(keepfd);
        if (sync_rc == 0 || errno != 117)
            return fail(tag, "SYNC was not rejected after fatal rollback");
        printf("%s: later SYNC rejected errno=117\n", tag);
        printf("%s: PASS\n", tag);
        return 0;
    }
    /* The next operation sends OP_SYNC. Rust must retain the zero-open pending
     * lifetime slot after the failed CLOSE and retry the same orphan cleanup. */
    if (fsync(keepfd) != 0) return fail(tag, "sync retry");
    if (close(keepfd) != 0) return fail(tag, "close keeper");
    if (unlink(keeper) != 0) return fail(tag, "remove keeper");
    sync();
    if (!close_expected)
        return fail(tag, "cleanup retried but kernel swallowed close EIO");
    printf("%s: PASS\n", tag);
    return 0;
}

static int test_iso(void)
{
    const char *tag = "UXFS_ISO";
    spawn_ufsd("/uiso", "3", "iso9660");
    if (wait_path("/uiso/hello.txt", 500))
        return fail(tag, "/uiso not visible");

    char buf[64];
    if (read_all("/uiso/hello.txt", buf, sizeof(buf)) <= 0 ||
        strcmp(buf, "hello iso9660 world\n") != 0)
        return fail(tag, "HELLO.TXT content");

    if (read_all("/uiso/sub/nested.txt", buf, sizeof(buf)) <= 0 ||
        strcmp(buf, "nested file content\n") != 0)
        return fail(tag, "NESTED.TXT content");

    DIR *d = opendir("/uiso");
    if (!d)
        return fail(tag, "opendir");
    int saw_sub = 0;
    struct dirent *ent;
    while ((ent = readdir(d)) != NULL)
        if (strcmp(ent->d_name, "sub") == 0)
            saw_sub = 1;
    closedir(d);
    if (!saw_sub)
        return fail(tag, "readdir missing SUB");

    printf("%s: PASS\n", tag);
    return 0;
}

/* The ntfs backend has opened read-write: verify mount/MFT parsing,
 * create-write-read-back, directory operations, deletion, and data
 * persistence across a SIGKILL restart (an in-tree end-to-end test of the
 * kernel ntfs write path). */
static int test_ntfs(void)
{
    const char *tag = "UXFS_NTFS";
    const char *mrk = "/untfs/RESTART.MRK";

    pid_t a = spawn_ufsd("/untfs", "4", "ntfs");
    if (wait_path("/untfs", 500))
        return fail(tag, "/untfs not visible");

    struct stat st;
    if (stat("/untfs", &st) != 0)
        return fail(tag, "stat /untfs failed");
    if (!S_ISDIR(st.st_mode)) {
        printf("UXFS_NTFS: dbg mode=%o size=%zu\n", st.st_mode,
               (size_t)st.st_size);
        return fail(tag, "root not a directory");
    }

    /* Create-write-read-back: an 8KB pseudorandom pattern covers
     * non-resident data streams and cluster allocation */
    if (roundtrip(tag, "/untfs", "NTFSBIN.BIN"))
        return 1;

    /* Directory ops: mkdir -> nested create and read -> delete the file
     * before rmdir */
    if (mkdir("/untfs/sub", 0755) != 0) {
        printf("%s: mkdir errno=%d\n", tag, errno);
        return fail(tag, "mkdir");
    }
    char npath[256];
    snprintf(npath, sizeof(npath), "%s/%s", "/untfs/sub", "NESTED.TXT");
    int fd = open(npath, O_CREAT | O_WRONLY, 0644);
    if (fd < 0)
        return fail(tag, "nested create");
    if (write(fd, "ntfs nested\n", 12) != 12) {
        close(fd);
        return fail(tag, "nested write");
    }
    close(fd);

    /* Persistence marker: must survive a restart across instances */
    fd = open(mrk, O_CREAT | O_WRONLY, 0644);
    if (fd < 0)
        return fail(tag, "create marker");
    if (write(fd, "survive-restart\n", 16) != 16) {
        close(fd);
        return fail(tag, "marker write");
    }
    close(fd);

    DIR *d = opendir("/untfs");
    if (!d)
        return fail(tag, "opendir");
    int saw_bin = 0, saw_sub = 0;
    struct dirent *ent;
    while ((ent = readdir(d)) != NULL) {
        if (strcmp(ent->d_name, "NTFSBIN.BIN") == 0)
            saw_bin = 1;
        if (strcmp(ent->d_name, "sub") == 0)
            saw_sub = 1;
    }
    closedir(d);
    if (!saw_bin || !saw_sub)
        return fail(tag, "readdir missing created entries");

    /* Crash-recovery drill: SIGKILL the instance -> unmount -> restart ->
     * data still there */
    if (kill_and_remount_ufsd(a, "/untfs", "4", "ntfs") != 0)
        return fail(tag, "remount after crash");
    if (wait_path(mrk, 500))
        return fail(tag, "instance B not visible");

    char buf[32];
    memset(buf, 0, sizeof(buf));
    if (read_all(mrk, buf, sizeof(buf)) != 16 ||
        strcmp(buf, "survive-restart\n") != 0)
        return fail(tag, "marker content lost across restart");

    memset(buf, 0, sizeof(buf));
    if (read_all(npath, buf, sizeof(buf)) != 12 ||
        strcmp(buf, "ntfs nested\n") != 0)
        return fail(tag, "nested content lost across restart");

    /* Cleanup: deleting the path reclaims both the clusters and the MFT
     * record */
    if (unlink("/untfs/NTFSBIN.BIN") != 0)
        return fail(tag, "unlink");
    if (unlink(npath) != 0)
        return fail(tag, "nested unlink");
    if (rmdir("/untfs/sub") != 0)
        return fail(tag, "rmdir");
    unlink(mrk);

    printf("%s: PASS\n", tag);
    return 0;
}

/* Crash-recovery drill: on the separate mount point /ufs2, verify the full
 * "kill the instance -> unmount -> restart -> data persists" contract (a
 * measured test of the recovery semantics in 06-user-fs.md). */
static int test_restart(void)
{
    const char *tag = "UXFS_RESTART";
    const char *mrk = "/ufs2/RESTART.MRK";

    pid_t a = spawn_ufsd("/ufs2", "1", "fat");
    if (wait_path(mrk ? "/ufs2" : mrk, 500))
        return fail(tag, "/ufs2 first instance not visible");

    int fd = open(mrk, O_CREAT | O_WRONLY, 0644);
    if (fd < 0)
        return fail(tag, "create marker");
    if (write(fd, "survive-restart\n", 16) != 16) {
        close(fd);
        return fail(tag, "marker write");
    }
    close(fd);

    if (kill_and_remount_ufsd(a, "/ufs2", "1", "fat") != 0)
        return fail(tag, "umount after crash");
    if (wait_path(mrk, 500))
        return fail(tag, "instance B not visible");

    char buf[32];
    memset(buf, 0, sizeof(buf));
    int fd2 = open(mrk, O_RDONLY);
    if (fd2 < 0)
        return fail(tag, "marker reopen");
    ssize_t n = read(fd2, buf, sizeof(buf) - 1);
    close(fd2);
    if (n != 16 || strcmp(buf, "survive-restart\n") != 0)
        return fail(tag, "marker content lost across restart");

    unlink(mrk);
    printf("%s: PASS\n", tag);
    return 0;
}

/* Verify the service's explicit graceful close path.  Unlike a kernel
 * poweroff or SIGKILL, umount2 shuts down the UXFS peer and requires UFSD to
 * commit its ext4 clean-state transition before the mount is detached. */
static int test_ext4_mount_state(int verify)
{
    const char *tag = verify ? "UXFS_EXT4_STATE_RESTART" : "UXFS_EXT4_STATE_CLEAN";
    const char *marker = "/uext4/MOUNT.STATE";
    pid_t service = spawn_ufsd("/uext4", "2", "ext4");
    if (service < 0 || wait_path("/uext4/hello.txt", 500))
        return fail(tag, "service mount");

    if (verify) {
        char bytes[32] = {0};
        if (read_all(marker, bytes, sizeof(bytes)) != 13 ||
            strcmp(bytes, "clean-reboot\n") != 0)
            return fail(tag, "marker missing after cold reboot");
    } else {
        int fd = open(marker, O_CREAT | O_TRUNC | O_WRONLY, 0644);
        if (fd < 0 || write(fd, "clean-reboot\n", 13) != 13 ||
            fsync(fd) != 0 || close(fd) != 0)
            return fail(tag, "write/fsync marker");
    }

    /* An open descriptor makes shutdown reject before teardown. The kernel
     * must restore admission only for this explicit pre-teardown response,
     * so the descriptor remains usable and can be closed before retry. */
    int held = open("/uext4/hello.txt", O_RDONLY);
    if (held < 0)
        return fail(tag, "open descriptor before shutdown preflight");
    errno = 0;
    if (umount2("/uext4", 0) == 0 || errno != EBUSY)
        return fail(tag, "open descriptor did not make shutdown EBUSY");
    char hello[64];
    if (read(held, hello, sizeof(hello)) <= 0)
        return fail(tag, "preflight EBUSY did not restore file service");
    if (close(held) != 0)
        return fail(tag, "close descriptor after preflight EBUSY");

    if (umount2("/uext4", 0) != 0)
        return fail(tag, "explicit umount2");
    int status = 0;
    if (waitpid(service, &status, 0) != service || !WIFEXITED(status) ||
        WEXITSTATUS(status) != 0)
        return fail(tag, "UFSD did not exit cleanly after peer shutdown");
    printf("%s: PASS explicit_umount=ok service_exit=0\n", tag);
    return 0;
}

int main(int argc, char **argv)
{
    if (argc == 2) {
        if (strcmp(argv[1], "lifetime") == 0)
            return test_ext4_open_unlink();
        if (strcmp(argv[1], "close-retry") == 0)
            return test_ext4_close_retry(0);
        if (strcmp(argv[1], "close-retry-multi") == 0)
            return test_ext4_close_retry(1);
        if (strcmp(argv[1], "close-quarantine") == 0)
            return test_ext4_close_retry(2);
        if (strcmp(argv[1], "ntfs") == 0)
            return test_ntfs();
        if (strcmp(argv[1], "readdir") == 0)
            return test_readdir_only();
        if (strcmp(argv[1], "mount-state-clean") == 0)
            return test_ext4_mount_state(0);
        if (strcmp(argv[1], "mount-state-verify") == 0)
            return test_ext4_mount_state(1);
        g_ext4_stop_stage = argv[1];
        if (strcmp(argv[1], "created") != 0 &&
            strcmp(argv[1], "renamed") != 0 &&
            strcmp(argv[1], "unlinked") != 0 &&
            strcmp(argv[1], "close-retry") != 0)
            return fail("UXFS_EXT4", "unknown stage");
        return test_ext4();
    }
    if (test_fat())
        return 1;
    if (test_ext4())
        return 1;
    if (test_iso())
        return 1;
    if (test_ntfs())
        return 1;
    if (test_restart())
        return 1;
    printf("UXFS_ALL: PASS\n");
    return 0;
}
